def write_json(path: Path, data: dict) -> None:
    path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")


def main() -> None:
    handled = []
    for number in range(1701, 1751):
        folder, explanation, payload = META[number]
        problem_dir = ROOT / folder
        if not problem_dir.is_dir():
            raise FileNotFoundError(f"Missing expected problem folder: {folder}")
        (problem_dir / "solution.py").write_text(SOLUTIONS[number], encoding="utf-8")
        (problem_dir / "EXPLANATION.md").write_text(
            f"# {number}\n\n{explanation}\n\nTime and space are chosen to fit the official constraints.\n",
            encoding="utf-8",
        )
        tests_dir = problem_dir / "tests"
        tests_dir.mkdir(exist_ok=True)
        write_json(tests_dir / "config.json", payload["config"])
        write_json(tests_dir / "cases.json", payload["cases"])
        handled.append(folder)
    print(f"Generated {len(handled)} problems:")
    for folder in handled:
        print(f"- {folder}")


if __name__ == "__main__":
    main()
